Here is a TypeScript implementation of a basic publish-subscribe event system with support for wildcard event topics. The wildcard `*` allows subscribers to listen to all events under a specific namespace or globally.

```typescript
type Callback = (...args: any[]) => void;

class EventEmitter {
  private events: Record<string, Callback[]> = {};

  /**
   * Subscribe to a specific event topic.
   * Supports wildcard topics such as `namespace.*` or `*`.
   * @param topic The event topic to subscribe to.
   * @param callback The callback to execute when the event is emitted.
   */
  on(topic: string, callback: Callback): void {
    if (!this.events[topic]) {
      this.events[topic] = [];
    }
    this.events[topic].push(callback);
  }

  /**
   * Unsubscribe from a specific event topic.
   * If no callback is specified, all callbacks for the topic will be removed.
   * @param topic The event topic to unsubscribe from.
   * @param callback Optional callback to remove.
   */
  off(topic: string, callback?: Callback): void {
    if (!this.events[topic]) return;

    if (callback) {
      this.events[topic] = this.events[topic].filter(cb => cb !== callback);
    } else {
      delete this.events[topic];
    }
  }

  /**
   * Emit an event with a specific topic and optional arguments.
   * Wildcard subscribers will also receive the event.
   * @param topic The event topic to emit.
   * @param args Optional arguments to pass to the callbacks.
   */
  emit(topic: string, ...args: any[]): void {
    // Execute callbacks for the specific topic
    if (this.events[topic]) {
      this.events[topic].forEach(callback => callback(...args));
    }

    // Execute callbacks for wildcard listeners
    const topicParts = topic.split('.');
    const wildcardTopics = [
      '*', // Global wildcard
      ...topicParts.map((_, index) =>
        [...topicParts.slice(0, index), '*'].join('.')
      )
    ];

    wildcardTopics.forEach(wildcardTopic => {
      if (this.events[wildcardTopic]) {
        this.events[wildcardTopic].forEach(callback => callback(...args));
      }
    });
  }
}

