Here is a JavaScript function to parse a CSV string into an array of objects, taking care of quoted fields that may contain commas or newlines. It supports a header row to define the keys for the resulting objects:

```javascript
function parseCSV(csvString) {
  const rows = [];
  let currentRow = [];
  let currentField = '';
  let insideQuotes = false;

  for (let i = 0; i < csvString.length; i++) {
    const char = csvString[i];
    const nextChar = csvString[i + 1];

    if (insideQuotes) {
      if (char === '"' && nextChar === '"') {
        // Escaped double-quote
        currentField += '"';
        i++; // Skip the next quote
      } else if (char === '"') {
        // End of quoted field
        insideQuotes = false;
      } else {
        // Inside quoted field
        currentField += char;
      }
    } else {
      if (char === '"') {
        // Start of quoted field
        insideQuotes = true;
      } else if (char === ',') {
        // End of field
        currentRow.push(currentField);
        currentField = '';
      } else if (char === '\n') {
        // End of row
        currentRow.push(currentField);
        rows.push(currentRow);
        currentRow = [];
        currentField = '';
      } else {
        // Regular character
        currentField += char;
      }
    }
  }

  // Add the last field and row if necessary
  if (currentField !== '' || currentRow.length > 0) {
    currentRow.push(currentField);
    rows.push(currentRow);
  }

  // Convert rows to an array of objects, using the first row as headers
  const headers = rows.shift();
  return rows.map(row => {
    const obj = {};
    headers.forEach((header, index) => {
      obj[header] = row[index] || '';
    });
    return obj;
  });
}

